(function () {
'use strict';
var Utils = window.Utils;
var HttpApi = window.HttpApi;
var article = null;
function render(data, recommendGoods) {
article = data;
var title = data.title || '文章详情';
var header = document.getElementById('article-header');
var tags = Array.isArray(data.tags) ? data.tags.filter(Boolean) : [];
var date = Utils.formatDate(data.update_date || data.create_date);
header.innerHTML = [
data.category ? '<span class="tag tag-primary">' + Utils.escapeHtml(data.category) + '</span>' : '',
'<h1>' + Utils.escapeHtml(title) + '</h1>',
'<div class="article-info">',
date ? '<span>' + Utils.escapeHtml(date) + '</span>' : '',
data.view_count ? '<span>' + Utils.num(data.view_count) + ' 阅读</span>' : '',
data.author ? '<span>' + Utils.escapeHtml(data.author) + '</span>' : '',
'</div>',
tags.length ? '<div class="chips">' + tags.map(function (t) {
return '<span class="tag">' + Utils.escapeHtml(t) + '</span>';
}).join('') + '</div>' : ''
].join('');
var coverSrc = Utils.firstImage(data.cover || data.image);
if (coverSrc) {
var cover = document.getElementById('article-cover');
cover.hidden = false;
cover.innerHTML = '<img src="' + Utils.escapeHtml(Utils.ossImg(coverSrc, { w: 960, h: 540 })) +
'" alt="' + Utils.escapeHtml(title) + '">';
}
document.getElementById('article-body').innerHTML = data.content
? Utils.sanitizeHtml(data.content)
: '<p>' + Utils.escapeHtml(data.summary || '暂无正文') + '</p>';
var actions = document.getElementById('article-actions');
actions.hidden = false;
if (data.source_url) {
var source = document.getElementById('article-source');
source.hidden = false;
source.href = Utils.safeUrl(data.source_url);
}
var favBtn = document.getElementById('article-fav');
function refreshFav() {
var faved = Utils.favorite.is('article', data._id);
favBtn.textContent = faved ? '已收藏' : '收藏';
favBtn.classList.toggle('is-active', faved);
}
favBtn.addEventListener('click', function () {
var added = Utils.favorite.toggle('article', data);
refreshFav();
Utils.toast(added ? '已收藏' : '已取消收藏');
Utils.track(added ? 'favorite_add' : 'favorite_remove', { id: data._id, type: 'article', from: 'detail' });
});
refreshFav();
document.getElementById('article-share').addEventListener('click', function () {
Utils.share({ title: title, url: location.href });
});
var goods = Array.isArray(recommendGoods) ? recommendGoods : [];
if (goods.length) {
document.getElementById('article-goods').hidden = false;
document.getElementById('article-goods-list').innerHTML = goods.map(function (g) {
return Utils.goodsCardHtml(g);
}).join('');
Utils.syncActionStates(document.getElementById('article-goods-list'));
}
var stores = Array.isArray(data.linkedStores) ? data.linkedStores : [];
if (stores.length) {
document.getElementById('article-stores').hidden = false;
document.getElementById('article-store-list').innerHTML = stores.map(function (s) {
return Utils.storeCardHtml(s);
}).join('');
}
Utils.setSeo({
title: title + ' - 东北电动车汇',
description: Utils.truncate(data.summary || data.content, 110),
canonical: location.origin + location.pathname + '?id=' + encodeURIComponent(data._id || ''),
type: 'article'
});
}
function init() {
var id = Utils.query('id');
if (!id) {
document.getElementById('article-header').innerHTML = Utils.emptyHtml(
'缺少文章参数',
'<a class="btn btn-outline btn-sm" href="/article/article.html">返回文章资讯</a>'
);
return;
}
Utils.track('article_detail_view', { id: id });
HttpApi.article.getDetail({ id: id }).then(function (res) {
var data = res && res.code === 0 ? res.data : null;
var articleData = data && (data.article || data);
if (articleData && articleData._id) {
render(articleData, data.recommendGoods);
return;
}
document.getElementById('article-header').innerHTML = Utils.emptyHtml(
'文章不存在或已删除',
'<a class="btn btn-outline btn-sm" href="/article/article.html">返回文章资讯</a>'
);
});
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
